import{_ as c,C as d,o,c as u,a2 as i,b as n,w as e,a as r,E as l,a3 as s}from"./chunks/framework.CgxQ0r6v.js";const b=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 4","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-VI/Lectura_Catedra_Evaluacion_4.md","filePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-VI/Lectura_Catedra_Evaluacion_4.md"}'),m={name:"materias/Proyecto_Sociotecnologico_II/documentacion/II-VI/Lectura_Catedra_Evaluacion_4.md"};function f(p,a,g,C,A,y){const t=d("Mermaid");return o(),u("div",null,[a[2]||(a[2]=i('<h1 id="manual-de-estudio-profundo-evaluacion-4" tabindex="-1">Manual de Estudio Profundo: Evaluación 4 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-4" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 4&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-vi" tabindex="-1">Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre VI) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-vi" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre VI)&quot;">​</a></h2><h3 id="eje-tematico-informe-final-portafolio-de-120-horas-y-socializacion-comunitaria" tabindex="-1">Eje Temático: Informe Final, Portafolio de 120 Horas y Socialización Comunitaria <a class="header-anchor" href="#eje-tematico-informe-final-portafolio-de-120-horas-y-socializacion-comunitaria" aria-label="Permalink to &quot;Eje Temático: Informe Final, Portafolio de 120 Horas y Socialización Comunitaria&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-culminacion-del-trayecto-ii" tabindex="-1">🧭 Introducción: La Culminación del Trayecto II <a class="header-anchor" href="#🧭-introduccion-la-culminacion-del-trayecto-ii" aria-label="Permalink to &quot;🧭 Introducción: La Culminación del Trayecto II&quot;">​</a></h2><p>La Evaluación 4 del Trimestre VI representa el acto académico y social más trascendental del Trayecto II: <strong>la presentación, defensa y socialización del Proyecto Sociotecnológico</strong>.</p><p>En este momento se integran los saberes acumulados durante un año académico completo: la investigación participativa, el modelado formal de software, la programación en tecnologías libres, el aseguramiento de calidad y la interacción directa con la comunidad. Además, en el marco de la legislación universitaria venezolana, esta fase acredita formalmente el cumplimiento del <strong>Servicio Comunitario (120 horas presenciales)</strong> exigido por la ley.</p><hr><h2 id="📑-capitulo-i-estructura-formal-del-informe-final-de-proyecto-uptt" tabindex="-1">📑 CAPÍTULO I: Estructura Formal del Informe Final de Proyecto UPTT <a class="header-anchor" href="#📑-capitulo-i-estructura-formal-del-informe-final-de-proyecto-uptt" aria-label="Permalink to &quot;📑 CAPÍTULO I: Estructura Formal del Informe Final de Proyecto UPTT&quot;">​</a></h2><p>El Informe Final es el documento científico y técnico definitivo que reposará en la biblioteca institucional de la universidad y en la comunidad.</p>',10)),(o(),n(s,null,{default:e(()=>[l(t,{id:"mermaid-26",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20INF%5B%22%F0%9F%93%91%20Estructura%20del%20Informe%20Final%20PST%20II%22%5D%0A%20%20%20%20INF%20--%3E%20P%5B%22%F0%9F%93%84%20P%C3%A1ginas%20Preliminares%22%5D%0A%20%20%20%20INF%20--%3E%20C1%5B%22%F0%9F%8F%9B%EF%B8%8F%20Cap%C3%ADtulo%20I%3A%20El%20Diagn%C3%B3stico%20y%20Contexto%20Comunitario%22%5D%0A%20%20%20%20INF%20--%3E%20C2%5B%22%F0%9F%93%9A%20Cap%C3%ADtulo%20II%3A%20Marco%20Referencial%20y%20Metodol%C3%B3gico%22%5D%0A%20%20%20%20INF%20--%3E%20C3%5B%22%F0%9F%92%BB%20Cap%C3%ADtulo%20III%3A%20Propuesta%20Tecnol%C3%B3gica%20y%20Modelado%22%5D%0A%20%20%20%20INF%20--%3E%20C4%5B%22%F0%9F%9A%80%20Cap%C3%ADtulo%20IV%3A%20Ejecuci%C3%B3n%2C%20Pruebas%20e%20Implantaci%C3%B3n%22%5D%0A%20%20%20%20INF%20--%3E%20CR%5B%22%F0%9F%8E%AF%20Conclusiones%20y%20Recomendaciones%22%5D%0A%20%20%20%20INF%20--%3E%20AN%5B%22%F0%9F%93%8E%20Referencias%20Bibliogr%C3%A1ficas%20y%20Anexos%22%5D%0A%0A%20%20%20%20style%20INF%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20P%20fill%3A%23475569%2Cstroke%3A%2394a3b8%2Ccolor%3A%23fff%0A%20%20%20%20style%20C1%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A%20%20%20%20style%20C2%20fill%3A%231e3a8a%2Cstroke%3A%233b82f6%2Ccolor%3A%23fff%0A%20%20%20%20style%20C3%20fill%3A%234338ca%2Cstroke%3A%236366f1%2Ccolor%3A%23fff%0A%20%20%20%20style%20C4%20fill%3A%2315803d%2Cstroke%3A%2322c55e%2Ccolor%3A%23fff%0A%20%20%20%20style%20CR%20fill%3A%2378350f%2Cstroke%3A%23f59e0b%2Ccolor%3A%23fff%0A%20%20%20%20style%20AN%20fill%3A%23701a75%2Cstroke%3A%23d946ef%2Ccolor%3A%23fff%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<h3 id="_1-1-paginas-preliminares" tabindex="-1">1.1 Páginas Preliminares <a class="header-anchor" href="#_1-1-paginas-preliminares" aria-label="Permalink to &quot;1.1 Páginas Preliminares&quot;">​</a></h3><ul><li><strong>Portada Oficial:</strong> Con cintillo institucional de la República y de la UPTT &quot;Mario Briceño Iragorry&quot;, título del proyecto, autores, tutores (académico y comunitario) y fecha.</li><li><strong>Acta de Veredicto / Aprobación del Jurado y de los Tutores.</strong></li><li><strong>Dedicatoria y Agradecimientos</strong> (opcionales).</li><li><strong>Índices:</strong> Índice General, Índice de Tablas, Índice de Figuras/Gráficos.</li><li><strong>Resumen Informativo:</strong> Máximo 300 palabras en un solo párrafo, estructurado con objetivo, metodología, resultados principales y 3 a 5 palabras clave (descriptores).</li></ul><h3 id="_1-2-capitulos-centrales" tabindex="-1">1.2 Capítulos Centrales <a class="header-anchor" href="#_1-2-capitulos-centrales" aria-label="Permalink to &quot;1.2 Capítulos Centrales&quot;">​</a></h3><ul><li><strong>Capítulo I: El Diagnóstico:</strong> Reseña histórica de la organización, caracterización demográfica, Árbol del Problema, Árbol de Objetivos, Justificación y Alcance.</li><li><strong>Capítulo II: Marco Referencial y Metodológico:</strong> Antecedentes de investigación, bases teóricas, bases legales (Ley de Infogobierno, CRBV), metodología de software seleccionada y justificada.</li><li><strong>Capítulo III: Propuesta Tecnológica y Modelado:</strong> Especificación de Requerimientos (RF y RNF), diagramas UML (casos de uso, actividades, secuencia, clases) y diseño de base de datos relacional (MER, MR y diccionario de datos).</li><li><strong>Capítulo IV: Ejecución, Pruebas e Implantación:</strong> Descripción de la arquitectura (MVC), matriz de pruebas funcionales y de aceptación, informe del plan de implantación y resultados de los talleres de capacitación comunitaria.</li><li><strong>Conclusiones y Recomendaciones:</strong> Conclusiones directas por cada objetivo específico y recomendaciones técnicas para la comunidad y para futuras investigaciones.</li></ul><hr><h2 id="⏱️-capitulo-ii-el-portafolio-de-evidencias-y-las-120-horas-comunitarias" tabindex="-1">⏱️ CAPÍTULO II: El Portafolio de Evidencias y las 120 Horas Comunitarias <a class="header-anchor" href="#⏱️-capitulo-ii-el-portafolio-de-evidencias-y-las-120-horas-comunitarias" aria-label="Permalink to &quot;⏱️ CAPÍTULO II: El Portafolio de Evidencias y las 120 Horas Comunitarias&quot;">​</a></h2><p>Según la <strong>Ley de Servicio Comunitario del Estudiante de Educación Superior</strong> y el Reglamento del PSI/T de la UPTT, los estudiantes deben certificar como mínimo <strong>ciento veinte (120) horas</strong> de vinculación directa en la comunidad.</p><h3 id="_2-1-componentes-del-portafolio-de-evidencias" tabindex="-1">2.1 Componentes del Portafolio de Evidencias <a class="header-anchor" href="#_2-1-componentes-del-portafolio-de-evidencias" aria-label="Permalink to &quot;2.1 Componentes del Portafolio de Evidencias&quot;">​</a></h3><ol><li><strong>Carta de Postulación y Carta de Aceptación Original</strong> emitida por el consejo comunal o institución al inicio del proyecto.</li><li><strong>Control de Asistencia de Horas Comunitarias:</strong> Formato oficial con fechas, número de horas por jornada, descripción breve de la actividad (diagnóstico, talleres, pruebas, instalación) y <strong>firma y sello del tutor comunitario en cada fila</strong>.</li><li><strong>Minutas de Reunión:</strong> Registro de acuerdos tomados en cada visita.</li><li><strong>Registro Fotográfico Cronológico:</strong> Evidencias visuales de los estudiantes trabajando con la comunidad, dictando los talleres y realizando la entrega del software.</li><li><strong>Carta de Culminación y Aval de Conformidad:</strong> Documento emitido por la máxima autoridad de la comunidad certificando que el sistema fue entregado a entera satisfacción.</li></ol><hr><h2 id="🎤-capitulo-iii-la-defensa-publica-y-socializacion-comunitaria" tabindex="-1">🎤 CAPÍTULO III: La Defensa Pública y Socialización Comunitaria <a class="header-anchor" href="#🎤-capitulo-iii-la-defensa-publica-y-socializacion-comunitaria" aria-label="Permalink to &quot;🎤 CAPÍTULO III: La Defensa Pública y Socialización Comunitaria&quot;">​</a></h2><p>La defensa final se realiza en dos escenarios complementarios:</p><ol><li><strong>Socialización en la Comunidad:</strong> Presentación abierta ante los voceros, vecinos y beneficiarios, donde se hace la entrega simbólica y operativa del sistema.</li><li><strong>Defensa Académica Institucional:</strong> Presentación formal ante el jurado evaluador designado por el Departamento de Informática de la UPTT.</li></ol>',13)),(o(),n(s,null,{default:e(()=>[l(t,{id:"mermaid-143",class:"mermaid",graph:"journey%0A%20%20%20%20title%20Ruta%20del%20D%C3%ADa%20de%20la%20Defensa%20de%20Proyecto%0A%20%20%20%20section%20Preparaci%C3%B3n%0A%20%20%20%20%20%20Verificaci%C3%B3n%20de%20equipos%20y%20proyector%3A%205%3A%20Estudiante%0A%20%20%20%20%20%20Copia%20local%20de%20BD%20y%20servidor%20listo%3A%205%3A%20Estudiante%0A%20%20%20%20section%20Exposici%C3%B3n%20(20%20min)%0A%20%20%20%20%20%20Contexto%20y%20Problema%20Comunitario%3A%204%3A%20Estudiante%0A%20%20%20%20%20%20Metodolog%C3%ADa%20y%20Modelado%20UML%2FBD%3A%204%3A%20Estudiante%0A%20%20%20%20%20%20Demostraci%C3%B3n%20del%20Software%20en%20Vivo%3A%205%3A%20Estudiante%2C%20Jurado%0A%20%20%20%20section%20Ciclo%20de%20Preguntas%0A%20%20%20%20%20%20Defensa%20de%20decisiones%20t%C3%A9cnicas%3A%204%3A%20Estudiante%2C%20Jurado%0A%20%20%20%20%20%20Veredicto%20y%20Firma%20de%20Actas%3A%205%3A%20Jurado%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<h3 id="_3-1-estructura-recomendada-de-las-diapositivas-maximo-15-a-18-laminas" tabindex="-1">3.1 Estructura Recomendada de las Diapositivas (Máximo 15 a 18 láminas) <a class="header-anchor" href="#_3-1-estructura-recomendada-de-las-diapositivas-maximo-15-a-18-laminas" aria-label="Permalink to &quot;3.1 Estructura Recomendada de las Diapositivas (Máximo 15 a 18 láminas)&quot;">​</a></h3><ul><li><strong>Lámina 1:</strong> Portada formal con título conciso y datos de los autores.</li><li><strong>Láminas 2-3:</strong> El Problema en la Comunidad (Árbol del Problema y Objetivos).</li><li><strong>Láminas 4-5:</strong> Justificación e impacto sociocomunitario.</li><li><strong>Láminas 6-7:</strong> Metodología de software y fases ejecutadas.</li><li><strong>Láminas 8-9:</strong> Modelado clave (Diagrama de Casos de Uso y Diagrama de Base de Datos).</li><li><strong>Láminas 10-12:</strong> <strong>Demostración en vivo de la aplicación (No capturas, el sistema corriendo en tiempo real).</strong></li><li><strong>Lámina 13:</strong> Resultados de las pruebas de usuario y talleres de capacitación.</li><li><strong>Láminas 14-15:</strong> Conclusiones, recomendaciones y agradecimientos.</li></ul><hr><h2 id="📝-conclusiones-y-criterios-de-evaluacion-final" tabindex="-1">📝 Conclusiones y Criterios de Evaluación Final <a class="header-anchor" href="#📝-conclusiones-y-criterios-de-evaluacion-final" aria-label="Permalink to &quot;📝 Conclusiones y Criterios de Evaluación Final&quot;">​</a></h2><p>El jurado evalúa cuatro aspectos clave mediante instrumentos estandarizados de coevaluación y autoevaluación:</p><ol><li><strong>Dominio Teórico-Metodológico:</strong> Claridad en la exposición de requerimientos, UML y bases de datos.</li><li><strong>Calidad y Funcionamiento del Software:</strong> Interfaz intuitiva, estabilidad, validación de errores y persistencia correcta en base de datos.</li><li><strong>Impacto y Pertinencia Social:</strong> Utilidad real para la comunidad, transferibilidad del conocimiento y cumplimiento de las 120 horas.</li><li><strong>Rigor del Informe Escrito:</strong> Redacción académica, apego a las normas de presentación y soporte documental completo de anexos.</li></ol>',6))])}const P=c(m,[["render",f]]);export{b as __pageData,P as default};
